UPDATE "Mission" SET "actionType" = 'TASK_COMPLETE' WHERE "type" IN ('TASK_COMPLETION','SPEND','EARN');
UPDATE "Mission" SET "actionType" = 'REFERRAL_SIGNUP' WHERE "type" = 'REFERRAL';
UPDATE "Mission" SET "isActive" = false WHERE "type" IN ('LOGIN_STREAK','SPEND','EARN');
ALTER TABLE "Mission" ADD CONSTRAINT "Mission_unlockMissionId_fkey" FOREIGN KEY ("unlockMissionId") REFERENCES "Mission"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE IF NOT EXISTS "UserMissionProgress" ("id" TEXT NOT NULL, "userId" TEXT NOT NULL, "missionId" TEXT NOT NULL, "progress" INTEGER NOT NULL DEFAULT 0, "claimedAt" TIMESTAMP(3), "claimedTiers" INTEGER[] DEFAULT ARRAY[]::INTEGER[], "joinedAt" TIMESTAMP(3), "lastActionAt" TIMESTAMP(3), "dayKey" TEXT, "dayCount" INTEGER NOT NULL DEFAULT 0, "notifiedComplete" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "UserMissionProgress_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "UserMissionProgress_userId_missionId_key" ON "UserMissionProgress"("userId", "missionId");
CREATE INDEX IF NOT EXISTS "UserMissionProgress_missionId_idx" ON "UserMissionProgress"("missionId");
ALTER TABLE "UserMissionProgress" ADD CONSTRAINT "UserMissionProgress_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "UserMissionProgress" ADD CONSTRAINT "UserMissionProgress_missionId_fkey" FOREIGN KEY ("missionId") REFERENCES "Mission"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE IF NOT EXISTS "MissionActionLog" ("id" TEXT NOT NULL, "missionId" TEXT NOT NULL, "userId" TEXT NOT NULL, "actionKey" TEXT NOT NULL, "dedupKey" TEXT NOT NULL, "units" INTEGER NOT NULL DEFAULT 1, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MissionActionLog_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX IF NOT EXISTS "MissionActionLog_missionId_userId_dedupKey_key" ON "MissionActionLog"("missionId", "userId", "dedupKey");
CREATE INDEX IF NOT EXISTS "MissionActionLog_userId_createdAt_idx" ON "MissionActionLog"("userId", "createdAt");
ALTER TABLE "MissionActionLog" ADD CONSTRAINT "MissionActionLog_missionId_fkey" FOREIGN KEY ("missionId") REFERENCES "Mission"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE INDEX CONCURRENTLY IF NOT EXISTS "Mission_isActive_order_idx" ON "Mission"("isActive", "order");
